#include <SDL.h>
#include <d3d9.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <vector>
#include <string>
static void require(bool value,const char*label){if(!value){std::fprintf(stderr,"FAIL: %s\n",label);std::exit(1);}}
int main(int argc,char**argv){
 require(SDL_Init(SDL_INIT_VIDEO)==0,SDL_GetError());auto*w=SDL_CreateWindow("Projected shadow fixture",0,0,64,64,SDL_WINDOW_HIDDEN|SDL_WINDOW_METAL);require(w,SDL_GetError());auto*api=Direct3DCreate9(D3D_SDK_VERSION);D3DPRESENT_PARAMETERS pp{};pp.BackBufferWidth=pp.BackBufferHeight=64;pp.BackBufferCount=1;pp.BackBufferFormat=D3DFMT_A8R8G8B8;pp.Windowed=TRUE;pp.hDeviceWindow=w;pp.SwapEffect=D3DSWAPEFFECT_DISCARD;IDirect3DDevice9*d=nullptr;require(SUCCEEDED(api->CreateDevice(0,D3DDEVTYPE_HAL,w,0,&pp,&d)),"device");
 IDirect3DTexture9 *silhouette=nullptr,*blur=nullptr;IDirect3DSurface9 *s=nullptr,*b=nullptr,*back=nullptr,*readback=nullptr;
 require(SUCCEEDED(d->CreateTexture(128,128,1,D3DUSAGE_RENDERTARGET,D3DFMT_R5G6B5,D3DPOOL_DEFAULT,&silhouette,nullptr)),"565 silhouette texture");require(SUCCEEDED(d->CreateTexture(128,128,1,D3DUSAGE_RENDERTARGET,D3DFMT_X8R8G8B8,D3DPOOL_DEFAULT,&blur,nullptr)),"blur texture");silhouette->GetSurfaceLevel(0,&s);blur->GetSurfaceLevel(0,&b);d->GetRenderTarget(0,&back);d->CreateOffscreenPlainSurface(64,64,D3DFMT_A8R8G8B8,D3DPOOL_SYSTEMMEM,&readback,nullptr);
 d->SetDepthStencilSurface(nullptr);d->SetRenderState(D3DRS_ZENABLE,FALSE);d->SetRenderState(D3DRS_CULLMODE,D3DCULL_NONE);d->SetRenderState(D3DRS_LIGHTING,FALSE);d->SetRenderState(D3DRS_FOGENABLE,FALSE);d->SetRenderState(D3DRS_ALPHATESTENABLE,FALSE);d->SetFVF(D3DFVF_XYZRHW|D3DFVF_DIFFUSE|D3DFVF_TEX1);d->SetSamplerState(0,D3DSAMP_MINFILTER,D3DTEXF_LINEAR);d->SetSamplerState(0,D3DSAMP_MAGFILTER,D3DTEXF_LINEAR);d->SetSamplerState(0,D3DSAMP_ADDRESSU,D3DTADDRESS_CLAMP);d->SetSamplerState(0,D3DSAMP_ADDRESSV,D3DTADDRESS_CLAMP);
 IDirect3DVertexShader9* retainedShader=nullptr;
 if(argc==2){std::ifstream file(std::string(argv[1])+"/weather/sea_sea2sunroad_vertex_shader.vso",std::ios::binary|std::ios::ate);require(bool(file),"original sun shader file");auto length=file.tellg();require(length>0&&size_t(length)%4==0,"shader bytes");std::vector<DWORD> code(size_t(length)/4);file.seekg(0);file.read((char*)code.data(),length);require(SUCCEEDED(d->CreateVertexShader(code.data(),&retainedShader)),"original sun shader");d->SetVertexShader(retainedShader);}
 struct V{float x,y,z,rhw;DWORD color;float u,v;};
 auto quad=[&](float lo,float hi,float du,float dv){V v[]={{lo,lo,.5f,.5f,0xffffffff,du,dv},{lo,hi,.5f,.5f,0xffffffff,du,1+dv},{hi,hi,.5f,.5f,0xffffffff,1+du,1+dv},{hi,lo,.5f,.5f,0xffffffff,1+du,dv}};require(SUCCEEDED(d->DrawPrimitiveUP(D3DPT_TRIANGLEFAN,2,v,sizeof(V))),"quad");};
 // Original shadow_model: black RT, actual caster silhouette via TFACTOR.
 d->SetRenderTarget(0,s);d->Clear(0,nullptr,D3DCLEAR_TARGET,0,1,0);d->BeginScene();d->SetRenderState(D3DRS_ALPHABLENDENABLE,FALSE);d->SetRenderState(D3DRS_TEXTUREFACTOR,0xff606040);d->SetTextureStageState(0,D3DTSS_COLOROP,D3DTOP_SELECTARG1);d->SetTextureStageState(0,D3DTSS_COLORARG1,D3DTA_TFACTOR);d->SetTextureStageState(1,D3DTSS_COLOROP,D3DTOP_DISABLE);quad(32,96,0,0);d->EndScene();
 // Original shadow_smooth: nine offset samples with additive ONE/ONE.
 d->SetRenderTarget(0,b);d->Clear(0,nullptr,D3DCLEAR_TARGET,0,1,0);d->BeginScene();d->SetTexture(0,silhouette);d->SetRenderState(D3DRS_ALPHABLENDENABLE,TRUE);d->SetRenderState(D3DRS_SRCBLEND,D3DBLEND_ONE);d->SetRenderState(D3DRS_DESTBLEND,D3DBLEND_ONE);d->SetRenderState(D3DRS_TEXTUREFACTOR,0xff1c1c1c);d->SetTextureStageState(0,D3DTSS_COLOROP,D3DTOP_MODULATE);d->SetTextureStageState(0,D3DTSS_COLORARG1,D3DTA_TEXTURE);d->SetTextureStageState(0,D3DTSS_COLORARG2,D3DTA_TFACTOR);d->SetTextureStageState(1,D3DTSS_COLOROP,D3DTOP_MODULATE);d->SetTextureStageState(1,D3DTSS_COLORARG1,D3DTA_CURRENT);d->SetTextureStageState(1,D3DTSS_COLORARG2,D3DTA_DIFFUSE);d->SetTextureStageState(2,D3DTSS_COLOROP,D3DTOP_DISABLE);for(int y=0;y<3;y++)for(int x=0;x<3;x++)quad(0,127,1.5f*(x-1)/127,1.5f*(y-1)/127);d->EndScene();
 // Original shadow_draw: ZERO/INVSRCCOLOR darkens only the silhouette footprint.
 d->SetRenderTarget(0,back);d->Clear(0,nullptr,D3DCLEAR_TARGET,0xffc0c0c0,1,0);d->BeginScene();d->SetTexture(0,blur);d->SetRenderState(D3DRS_SRCBLEND,D3DBLEND_ZERO);d->SetRenderState(D3DRS_DESTBLEND,D3DBLEND_INVSRCCOLOR);d->SetRenderState(D3DRS_TEXTUREFACTOR,0xff808080);d->SetTextureStageState(0,D3DTSS_COLOROP,D3DTOP_MODULATE2X);d->SetTextureStageState(1,D3DTSS_COLOROP,D3DTOP_DISABLE);quad(0,64,0,0);d->EndScene();require(SUCCEEDED(d->GetRenderTargetData(back,readback)),"readback");D3DLOCKED_RECT lock{};readback->LockRect(&lock,nullptr,D3DLOCK_READONLY);auto pixel=[&](int x,int y){DWORD p;std::memcpy(&p,(char*)lock.pBits+y*lock.Pitch+x*4,4);return p;};DWORD center=pixel(32,32),outside=pixel(4,4);readback->UnlockRect();require((outside&0xffffff)==0xc0c0c0,"outside shadow unchanged");require(((center>>16)&255)>100&&((center>>16)&255)<140,"silhouette darkens receiver");require((center&255)>((center>>16)&255),"colored silhouette preserved through both RTs");
 if(retainedShader){IDirect3DVertexShader9*bound=nullptr;d->GetVertexShader(&bound);require(bound==retainedShader,"POSITIONT bypass retains bound VS state");bound->Release();d->SetFVF(D3DFVF_XYZ|D3DFVF_DIFFUSE|D3DFVF_TEX1);V invalid[3]{};require(FAILED(d->DrawPrimitiveUP(D3DPT_TRIANGLELIST,1,invalid,sizeof(V))),"ordinary XYZ does not ignore incompatible shader");d->SetVertexShader(nullptr);retainedShader->Release();}
 std::printf("PASS: original silhouette/9-tap additive blur/multiplicative receiver, center=%08x outside=%08x, retained-VS=%s\n",center,outside,argc==2?"tested":"not requested");s->Release();b->Release();back->Release();readback->Release();silhouette->Release();blur->Release();d->Release();api->Release();SDL_DestroyWindow(w);SDL_Quit();
}
